use crate::common;
use rust_xlsxwriter::{PivotTable, PivotTableValueField, Workbook, XlsxError};

// Create a rust_xlsxwriter file to compare against an Excel file.
fn create_new_xlsx_file_1(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet();

    // Write the headers.
    worksheet.write_string(0, 0, "Region")?;
    worksheet.write_string(0, 1, "Item")?;
    worksheet.write_string(0, 2, "Volume")?;
    worksheet.write_string(0, 3, "Month")?;

    // Write the data used in the pivot table.
    let data = common::get_autofilter_data();
    for (row, data) in data.iter().enumerate() {
        let row = 1 + row as u32;
        worksheet.write_string(row, 0, data.0)?;
        worksheet.write_string(row, 1, data.1)?;
        worksheet.write_number(row, 2, data.2)?;
        worksheet.write_string(row, 3, data.3)?;
    }

    let pivot_table = PivotTable::new()
        .set_data_source("Sheet1", 0, 0, 50, 3)
        .add_row_field("Region")
        .add_value_field(&PivotTableValueField::new("Volume"));

    let worksheet = workbook.add_worksheet();
    worksheet.add_pivot_table(2, 0, &pivot_table)?;

    workbook.save(filename)?;

    Ok(())
}

// Test with a low memory source worksheet and explicit field names.
#[cfg(feature = "constant_memory")]
fn create_new_xlsx_file_2(filename: &str) -> Result<(), XlsxError> {
    let mut workbook = Workbook::new();

    let worksheet = workbook.add_worksheet_with_low_memory()?;

    // Write the headers.
    worksheet.write_string(0, 0, "Region")?;
    worksheet.write_string(0, 1, "Item")?;
    worksheet.write_string(0, 2, "Volume")?;
    worksheet.write_string(0, 3, "Month")?;

    // Write the data used in the pivot table.
    let data = common::get_autofilter_data();
    for (row, data) in data.iter().enumerate() {
        let row = 1 + row as u32;
        worksheet.write_string(row, 0, data.0)?;
        worksheet.write_string(row, 1, data.1)?;
        worksheet.write_number(row, 2, data.2)?;
        worksheet.write_string(row, 3, data.3)?;
    }

    let pivot_table = PivotTable::new()
        .set_data_source("Sheet1", 0, 0, 50, 3)
        .set_field_names(&["Region", "Item", "Volume", "Month"])
        .add_row_field("Region")
        .add_value_field(&PivotTableValueField::new("Volume"));

    let worksheet = workbook.add_worksheet();
    worksheet.add_pivot_table(2, 0, &pivot_table)?;

    workbook.save(filename)?;

    Ok(())
}

#[test]
fn test_pivot_table02_1() {
    let test_runner = common::TestRunner::new()
        .set_name("pivot_table02")
        .set_function(create_new_xlsx_file_1)
        .unique("1")
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}

#[test]
#[cfg(feature = "constant_memory")]
fn test_pivot_table02_2() {
    let test_runner = common::TestRunner::new()
        .set_name("pivot_table02")
        .set_function(create_new_xlsx_file_2)
        .unique("2")
        .ignore_worksheet_spans()
        .initialize();

    test_runner.assert_eq();
    test_runner.cleanup();
}
